-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('listening-better', 'Listening Better', 'For anyone who notices they are planning their reply while the other person is still talking. Each day is one small way to listen more fully, so the people around you feel heard and conversations get easier.', 'Communication', 365, array['Communication', 'Relationships']::text[], 1, '2026-09-26T17:00:00+00:00'::timestamptz),
  ('getting-outside-every-day', 'Getting Outside Every Day', 'For anyone whose days pass between four walls and a screen. Each day is one small reason to step outside, in any weather, so fresh air and daylight become a regular part of how you feel.', 'Wellbeing', 365, array['Self-Care', 'Mindfulness']::text[], 1, '2026-09-26T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('listening-better', 'getting-outside-every-day');

